#ifndef YSF_DEMODULATOR_H
#define YSF_DEMODULATOR_H

#ifndef __cplusplus
#error This header is C++ only!
#endif

#include <cstddef>
#include <cstdint>
#include <memory>
#include "core/audio_path.h"
#include "core/audio_stream.h"
#include "protocols/YSF/Constants.hpp"

namespace YSF
{

/**
 * Event generated by the YSF receiver.
 */
struct Event {
    enum Type : uint8_t {
        FRAME, ///< Frame received, see frame
        LOST   ///< Synchronisation lost, no sync for too long
    } type;

    /// FRAME only: the sync was found in this frame. Frames without sync
    /// are only reported after a sync has been found, at the same position
    /// in the following frames.
    bool sync;

    /// FRAME only: frame bits, sync first
    uint8_t frame[FRAME_BYTES];
};

/**
 * YSF receiver: 4FSK demodulation of the baseband sampled at 24 kHz, frame
 * synchronisation and symbol decisions. Platform independent.
 */
class Receiver
{
public:
    /// Input sample rate, in Hz
    static constexpr uint32_t SAMPLE_RATE = 24000;

    /// Input samples per symbol
    static constexpr size_t SAMPLES_PER_SYMBOL = SAMPLE_RATE / SYMBOL_RATE;

    /// Frames without sync before the synchronisation is lost
    static constexpr size_t MAX_LOST_FRAMES = 8;

    /// Capacity of the event queue
    static constexpr size_t EVENT_QUEUE_SIZE = 3;

    /**
     * Constructor.
     */
    Receiver();

    /**
     * Destructor.
     */
    ~Receiver();

    /**
     * Clear the receiver state, history included.
     */
    void reset();

    /**
     * Drop the synchronisation and look for a new sync anywhere.
     */
    void unlock();

    /**
     * Invert the phase of the input signal.
     *
     * @param invert: true to invert the input.
     */
    void invertPhase(bool invert);

    /**
     * Process a block of baseband samples.
     *
     * @param samples: samples at SAMPLE_RATE.
     * @param count: number of samples.
     */
    void process(const int16_t *samples, size_t count);

    /**
     * Pop the oldest event from the queue.
     *
     * @param ev: the event.
     * @return true if there was an event.
     */
    bool popEvent(Event &ev);

    /**
     * @return true if events are queued.
     */
    bool hasEvents() const;

private:
    /// Samples of a frame (100 ms), length of the sample history
    static constexpr size_t FRAME_SAMPLES = FRAME_SYMBOLS * SAMPLES_PER_SYMBOL;

    /// Taps of the receive filter
    static constexpr size_t FILTER_TAPS = 41;

    /**
     * Remove the DC level and apply the receive filter to a sample.
     */
    int16_t filter(int16_t raw);

    /**
     * Look for the sync ending at the current sample.
     *
     * @param first: true when not locked yet.
     */
    void correlateSync(bool first);

    /**
     * Correlation with the sync of the symbols ending at a sample.
     */
    int32_t correlate(size_t last) const;

    /**
     * Timing of the symbols between the samples, from the correlation peak
     * of the last sync, in 1/256 of a sample.
     */
    int16_t estimateTiming() const;

    /**
     * Turn symbols of the history into bits.
     */
    void samplesToBits(size_t start, size_t count, uint8_t *bits,
                       int16_t centre, int16_t threshold, int16_t timing) const;

    /**
     * Emit the frame ending at the current sample.
     */
    void endOfFrame();

    /**
     * Queue an event, dropping the oldest one if the queue is full.
     */
    void pushEvent(const Event &ev);

    bool inverted;        ///< Input phase inversion
    bool locked;          ///< Locked on a transmission
    bool haveSync;        ///< Sync found in the current frame
    bool haveEnd;         ///< endPtr is valid
    uint8_t bitPtr;       ///< Current sampling phase, 0 to 4
    uint8_t lostCount;    ///< Frames since the last sync
    uint8_t averagePtr;   ///< Position in centre and threshold
    uint8_t filterPtr;    ///< Position in filterBuffer
    uint16_t dataPtr;     ///< Current position in buffer
    uint16_t syncPtr;     ///< Position of the last sync symbol
    uint16_t endPtr;      ///< One sample after the end of the frame
    int16_t timing;       ///< Symbol timing offset, 1/256 sample
    int32_t maxCorr;      ///< Best sync correlation in this frame
    int16_t centre[4];    ///< Last centre levels
    int16_t threshold[4]; ///< Last decision thresholds
    float dcLevel;        ///< DC level estimate
    float dcPrevIn;       ///< Previous input of the DC estimator
    int16_t filterBuffer[FILTER_TAPS]; ///< Receive filter history

    /// Received symbol signs, one register per sampling phase, newest in
    /// the least significant position, 1 for a positive sample
    uint32_t bitBuffer[SAMPLES_PER_SYMBOL];

    /// Sample history, one frame long
    int16_t buffer[FRAME_SAMPLES];

    Event events[EVENT_QUEUE_SIZE]; ///< Event queue
    uint8_t eventHead;              ///< Oldest event in the queue
    uint8_t eventCount;             ///< Events in the queue
};

/**
 * YSF demodulator: baseband sampling through the audio stream, feeding the
 * receiver.
 */
class Demodulator
{
public:
    /**
     * Constructor.
     */
    Demodulator();

    /**
     * Destructor.
     */
    ~Demodulator();

    /**
     * Allocate the buffers and the receiver.
     */
    void init();

    /**
     * Stop the sampling and free the buffers.
     */
    void terminate();

    /**
     * Open the baseband input path and start sampling.
     */
    void startBasebandSampling();

    /**
     * Stop sampling and release the baseband input path.
     */
    void stopBasebandSampling();

    /**
     * Process the next block of baseband samples, blocking until available.
     *
     * @param invertPhase: invert the phase of the baseband signal.
     * @return true if the receiver has events.
     */
    bool update(bool invertPhase = false);

    /**
     * Pop the oldest receiver event.
     *
     * @param ev: the event.
     * @return true if there was an event.
     */
    bool popEvent(Event &ev);

    /**
     * Drop the synchronisation, see Receiver::unlock().
     */
    void unlock();

private:
    /// Samples of half the baseband buffer: 20 ms
    static constexpr size_t SAMPLE_BUF_SIZE = 480;

    std::unique_ptr<int16_t[]> basebandBuffer; ///< Baseband double buffer
    std::unique_ptr<Receiver> receiver;        ///< Receiver
    streamId basebandId;                       ///< Baseband input stream
    pathId basebandPath;                       ///< Baseband input path
};

} // namespace YSF

#endif // YSF_DEMODULATOR_H
